 if slug=='logarithmic-series':return result(record,[r'\frac1{1-t}=\sum_{j=0}^\infty t^j\qquad\left(0\le t\le '+tex(r)+r'<1\right)',T('The geometric series converges uniformly on this closed interval, so it can be integrated term by term.'),r'\sum_{k=1}^\infty\frac{r^k}{k}=\int_0^r\frac{\mathrm dt}{1-t}=-\ln(1-r),\qquad r='+tex(r),r'-\ln\left('+tex(1-r)+r'\right)='+tex(A)],[ck('The logarithm is the primitive of the geometric kernel',s.diff(-s.log(1-x),x),1/(1-x)),ck('Concrete logarithmic value agrees exactly',s.expand_log(-s.log(1-r),force=True),s.expand_log(A,force=True)),theorem('Uniform termwise integration',['The closed integration interval lies strictly inside the unit radius.'])],['missing-integration-endpoints'])
