 if slug=='negative-binomial':return result(record,[r'\sum_{k=0}^\infty r^{k+2}=\frac{r^2}{1-r}\qquad(|r|<1)',r'\frac12\frac{\mathrm d^2}{\mathrm dr^2}\frac{r^2}{1-r}=\sum_{k=0}^\infty\frac{(k+2)(k+1)}2r^k=\sum_{k=0}^\infty\binom{k+2}{2}r^k=\frac1{(1-r)^3}',r'r='+tex(r)+r'\quad\Longrightarrow\quad\frac1{(1-r)^3}='+tex(A)],[ck('The shifted geometric derivative supplies the binomial coefficient',s.diff(x*x/(1-x),x,2)/2,(1-x)**-3),ck('Substitution gives the concrete sum',(1-r)**-3,A)],['coefficient-identity-not-derived'])
 if slug=='cubic-telescope':return result(record,[r'\frac1{(k+'+tex(m)+r')(k+'+tex(m+1)+r')(k+'+tex(m+2)+r')}=\frac12\left(\frac1{(k+'+tex(m)+r')(k+'+tex(m+1)+r')}-\frac1{(k+'+tex(m+1)+r')(k+'+tex(m+2)+r')}\right)',r'\sum_{k=0}^N\frac1{(k+'+tex(m)+r')(k+'+tex(m+1)+r')(k+'+tex(m+2)+r')}=\frac1{2\cdot'+tex(m)+r'\cdot'+tex(m+1)+r'}-\frac1{2(N+'+tex(m+1)+r')(N+'+tex(m+2)+r')}',T('The last endpoint tends to zero as the upper index tends to infinity.')],[ck('The three-factor decomposition is exact',1/((k+m)*(k+m+1)*(k+m+2)),(1/((k+m)*(k+m+1))-1/((k+m+1)*(k+m+2)))/2),ck('The surviving endpoint is the original answer',1/(2*m*(m+1)),A)],['missing-telescoping-normalization'])
 if slug=='quadratic-weight':return result(record,[r'\sum_{k=0}^\infty r^k=\frac1{1-r},\qquad\sum_{k=1}^\infty kr^k=\frac r{(1-r)^2}\quad(|r|<1)',r'\sum_{k=1}^\infty k^2r^k=r\frac{\mathrm d}{\mathrm dr}\left(\frac r{(1-r)^2}\right)=\frac{r(1+r)}{(1-r)^3}',r'r='+tex(r)+r'\quad\Longrightarrow\quad\frac{r(1+r)}{(1-r)^3}='+tex(A)],[ck('The weighted derivative produces an ordinary square, not a falling factorial',x*s.diff(x/(1-x)**2,x),x*(1+x)/(1-x)**3),ck('Concrete substitution',r*(1+r)/(1-r)**3,A)],['ordinary-versus-factorial-moment'])
 if slug=='weighted-binomial-total':return result(record,[r'(1+x)^{'+tex(m)+r'}=\sum_{k=0}^{'+tex(m)+r'}\binom{'+tex(m)+r'}k x^k',r'x\frac{\mathrm d}{\mathrm dx}(1+x)^{'+tex(m)+r'}='+tex(m)+r'x(1+x)^{'+tex(m-1)+r'}=\sum_{k=0}^{'+tex(m)+r'}k\binom{'+tex(m)+r'}k x^k',r'x=1\quad\Longrightarrow\quad\sum_{k=0}^{'+tex(m)+r'}k\binom{'+tex(m)+r'}k='+tex(m)+r'\cdot2^{'+tex(m-1)+'}='+tex(A)],[ck('Differentiated finite polynomial matches every weighted coefficient',x*s.diff((1+x)**m,x),sum(j*s.binomial(m,j)*x**j for j in range(int(m)+1)))],['missing-differentiated-polynomial'])
 if slug=='power-series-ratio-radius':return result(record,[r'b_k(x)=\frac{(k!)^2}{(2k)!}('+tex(m)+r'x)^k',r'\left|\frac{b_{k+1}(x)}{b_k(x)}\right|=\frac{(k+1)^2}{(2k+2)(2k+1)}\,'+tex(m)+r'|x|\longrightarrow\frac{'+tex(m)+r'|x|}{4}\qquad(x\ne0)',r'\frac{'+tex(m)+r'|x|}{4}<1\quad\Longleftrightarrow\quad|x|<'+tex(4/m),T('The series converges at the center as well. Endpoint behavior does not change its radius.'),r'R='+tex(A)],[ck('The factorial coefficient ratio has the displayed limit',s.limit((k+1)**2/((2*k+2)*(2*k+1)),k,s.oo),R(1,4)),ck('Solving the unit-ratio threshold yields the radius',4/m,A)],['factorial-ratio-not-shown'])
 if slug=='integral-tail-bound':return result(record,[r'x^{-3}>0,\qquad\frac{\mathrm d}{\mathrm dx}x^{-3}=-3x^{-4}<0\quad(x>0)',r'\frac1{k^3}\le\int_{k-1}^k x^{-3}\,\mathrm dx\qquad(k\ge'+tex(m+1)+r')',r'\sum_{k='+tex(m+1)+r'}^\infty\frac1{k^3}\le\int_{'+tex(m)+r'}^\infty x^{-3}\,\mathrm dx=\left[-\frac1{2x^2}\right]_{'+tex(m)+r'}^\infty=\frac1{2\cdot'+tex(m)+r'^2}='+tex(A)],[ck('The displayed primitive differentiates correctly',s.diff(-1/(2*x*x),x),x**-3),ck('The upper comparison integral has the actual lower endpoint',s.integrate(x**-3,(x,m,s.oo)),A)],['bound-versus-exact-sum','comparison-direction-not-justified'])
 if slug=='alternating-error':return result(record,[r'b_k=\frac1k>0,\qquad b_{k+1}<b_k,\qquad\lim_{k\to\infty}b_k=0',r'S=\sum_{k=1}^\infty\frac{(-1)^{k+1}}k,\qquad S_{'+tex(m)+r'}=\sum_{k=1}^{'+tex(m)+r'}\frac{(-1)^{k+1}}k',T('The alternating-series remainder theorem bounds the absolute error by the first omitted magnitude.'),r'|S-S_{'+tex(m)+r'}|\le b_{'+tex(m+1)+r'}=\frac1{'+tex(m+1)+'}='+tex(A)],[ck('The first omitted index is one after the final included term',1/(m+1),A),ck('The decreasing magnitudes tend to zero',s.limit(1/k,k,s.oo),0),theorem('Alternating-series remainder bound',['Positive magnitudes decrease to zero; terms one through the displayed integer are included.'])],['error-bound-versus-error-value'])
 if slug=='harmonic-generating':return result(record,[r'H_k=\sum_{j=1}^k\frac1j,\qquad r='+tex(r)+r'\in(0,1)',T('All terms in the expanded double sum are nonnegative, so Tonelli permits reversing the triangular summation region.'),r'\sum_{k=1}^\infty H_kr^k=\sum_{j=1}^\infty\frac1j\sum_{k=j}^\infty r^k=\frac1{1-r}\sum_{j=1}^\infty\frac{r^j}{j}',r'\sum_{j=1}^\infty\frac{r^j}{j}=\int_0^r\frac{\mathrm dt}{1-t}=-\ln(1-r)',r'\sum_{k=1}^\infty H_kr^k=-\frac{\ln(1-r)}{1-r}='+tex(A)],[ck('The logarithmic primitive is correct',s.diff(-s.log(1-x),x),1/(1-x)),ck('The concrete generating value agrees',s.expand_log(-s.log(1-r)/(1-r),force=True),s.expand_log(A,force=True)),theorem('Tonelli and interior geometric integration',['The ratio is positive and below one. The final finite logarithmic expression establishes convergence.'])],['undefined-harmonic-or-ratio-symbol','missing-triangular-sum-reversal'])
 if slug=='Catalan-generating':return result(record,[r'(1-t)^{-1/2}=\sum_{k=0}^\infty\binom{2k}{k}\frac{t^k}{4^k}\qquad(|t|<1)',r'r='+tex(r)+r'\in(0,1),\qquad\frac1r\int_0^r(1-t)^{-1/2}\,\mathrm dt=\sum_{k=0}^\infty\frac{\binom{2k}{k}}{(k+1)4^k}r^k',T('Uniform convergence on the closed integration interval permits integration term by term. The square root is the positive branch.'),r'\frac1r[-2\sqrt{1-t}]_0^r=\frac{2(1-\sqrt{1-r})}{r}='+tex(A)],[ck('The half-power primitive is exact',s.diff(-2*s.sqrt(1-x),x),(1-x)**-R(1,2)),ck('The integrated coefficient includes the required index factor',s.integrate(x**k,(x,0,r))/r,r**k/(k+1)),ck('Actual branch and argument',2*(1-s.sqrt(1-r))/r,A)],['missing-normalization-after-integration','square-root-branch-unstated'])
 if slug=='log-integrated-geometric':return result(record,[r'r='+tex(r)+r'\in(0,1),\qquad\frac1{k(k+1)}=\frac1k-\frac1{k+1}',r'\sum_{k=1}^\infty\frac{r^k}{k}=-\ln(1-r)',r'\sum_{k=1}^\infty\frac{r^k}{k+1}=\frac1r\left(\sum_{j=1}^\infty\frac{r^j}{j}-r\right)=\frac{-\ln(1-r)-r}{r}',r'\sum_{k=1}^\infty\frac{r^k}{k(k+1)}=1+\left(\frac1r-1\right)\ln(1-r)='+tex(A)],[ck('The denominator splits into consecutive reciprocal factors',1/(k*(k+1)),1/k-1/(k+1)),ck('The index-shift subtraction reduces to the displayed expression',-s.log(1-x)-(-s.log(1-x)-x)/x,1+(1/x-1)*s.log(1-x)),ck('Actual interior argument',1+(1/r-1)*s.log(1-r),A)],['missing-index-correction'])
